WITH base AS (SELECT *, DAY(start_date) AS start_date_day FROM subscriptions WHERE (end_date > '2025-03-01' AND customer_id IS NULL) OR monthly_fee > 140), subscriptions_stats AS (SELECT status, DATE_FORMAT(start_date, 'yyyy-MM') AS start_month, MIN(start_date) AS first_start_date FROM base GROUP BY status, DATE_FORMAT(start_date, 'yyyy-MM')) SELECT status, start_month, first_start_date FROM subscriptions_stats ORDER BY status, 3;
